"""Virtual database connection state."""

from typing import Any, Dict


class DBConnection:
    def __init__(self):
        self.storage: Dict[str, Any] = {}
        self.is_open: bool = True

repo_files.manager.py:
"""Database transaction manager orchestrator."""

from typing import Any, Dict, Optional
from connection import DBConnection
from transaction import TransactionSession


class TransactionManager:
    def __init__(self, conn: DBConnection):
        self.conn = conn
        self.current_tx: Optional[TransactionSession] = None

    def begin(self) -> TransactionSession:
        self.current_tx = TransactionSession(self.conn)
        return self.current_tx

    def write_record(self, key: str, value: Any) -> None:
        if not self.current_tx:
            raise RuntimeError("No active transaction")
        self.current_tx.active_data[key] = value

    def read_record(self, key: str) -> Optional[Any]:
        if self.current_tx:
            return self.current_tx.active_data.get(key)
        return self.conn.storage.get(key)
